      {term:"blowing up",desc:"Blow = soprar. Com up, encher algo com ar.",ex:[{en:"I am blowing up some balloons",pt:"Eu estou enchendo alguns balões"},{en:"I am blowing up many balloons",pt:"Eu estou enchendo muitos balões"}]},
      {term:"turning down",desc:"Turn = virar/girar. Com down, abaixar volume/intensidade.",ex:[{en:"I am turning down the speakers",pt:"Eu estou abaixando o volume das caixas de som"},{en:"I am turning down the heating",pt:"Eu estou abaixando o aquecimento"}]},
      {term:"turning up",desc:"Com up, aumentar volume/intensidade.",ex:[{en:"I am turning up the speakers",pt:"Eu estou aumentando o volume das caixas de som"},{en:"I am turning up the heating",pt:"Eu estou aumentando o aquecimento"}]},
      {term:"hung out",desc:"Hung = passado de hang (pendurar). Com out, encontrar-se com alguém em algum lugar.",ex:[{en:"We hung out at the mall yesterday",pt:"Nós nos encontramos no shopping ontem"},{en:"We hung out at the park last week",pt:"Nós nos encontramos no parque semana passada"}]},
      {term:"had a blast",desc:"Had = passado de have. Com a blast, aproveitar muito bem um momento.",ex:[{en:"We had a blast at your party",pt:"Nós curtimos muito na sua festa"},{en:"We had a blast at the bar",pt:"Nós curtimos muito no bar"}]},
      {term:"pulled off",desc:"Pull = puxar. Com off, conseguir fazer algo difícil.",ex:[{en:"I have pulled off a remarkable party",pt:"Eu consegui fazer uma festa memorável"},{en:"I have pulled off a great round",pt:"Eu consegui fazer um ótimo round"}]},
      {term:"throw a party",desc:"Não traduza ao pé da letra. Throw = jogar; throw a party = dar uma festa.",ex:[{en:"I will throw a pool party",pt:"Eu vou fazer uma festa na piscina"},{en:"I will throw a holiday party",pt:"Eu vou fazer uma festa de feriado"}]}
