      {term:"take out",desc:"Take = levar. Com out, levar algo para fora do ambiente.",ex:[{en:"I take out the trash every day",pt:"Eu tiro o lixo todo dia"},{en:"I take out the trash every week",pt:"Eu tiro o lixo toda semana"}]},
      {term:"throw away",desc:"Throw = lançar. Com away, jogar algo fora.",ex:[{en:"I throw away worn out boxes",pt:"Eu jogo fora caixas estragadas"},{en:"I throw away old magazines",pt:"Eu jogo fora revistas velhas"}]},
      {term:"put on",desc:"Put = colocar. Com on (no contexto), colocar música pra tocar.",ex:[{en:"I put on some music to work",pt:"Eu coloco música para trabalhar"},{en:"I put on some music to shower",pt:"Eu coloco música pra tomar banho"}]},
      {term:"blown out",desc:"Blow = soprar. Com out, apagar uma vela/fogo assoprando.",ex:[{en:"I have blown out the candle",pt:"Eu apaguei a vela"},{en:"I have blown out the fire",pt:"Eu apaguei o fogo"}]},
      {term:"put out",desc:"Com out, apagar uma luz/vela/fogo.",ex:[{en:"I have put out the fire",pt:"Eu apaguei o fogo"},{en:"I have put out the incense",pt:"Eu apaguei o incenso"}]},
      {term:"taken out",desc:"Take = pegar. Com out, remover algo de uma superfície.",ex:[{en:"I have taken out the picture from the wall",pt:"Eu tirei o quadro da parede"},{en:"I have taken out the notice from the board",pt:"Eu tirei o aviso do quadro"}]},
      {term:"turned on",desc:"Turn = girar. Com on, ligar um dispositivo.",ex:[{en:"I have turned on the TV",pt:"Eu liguei a televisão"},{en:"I have turned on the light",pt:"Eu liguei a luz"}]},
      {term:"turned off",desc:"Com off, desligar um dispositivo.",ex:[{en:"I have turned off the heating",pt:"Eu desliguei o aquecimento"},{en:"I have turned off the stove",pt:"Eu desliguei o fogão"}]},
      {term:"tidied up",desc:"Tidy = organizar. Com up, arrumar por completo.",ex:[{en:"I have tidied up the living room this morning",pt:"Eu arrumei a sala de estar hoje de manhã"},{en:"I have tidied up my bedroom today",pt:"Eu arrumei meu quarto hoje"}]},
      {term:"put away",desc:"Com away, ajuntar e colocar no devido lugar.",ex:[{en:"I have put away all the toys",pt:"Eu ajuntei todos os brinquedos"},{en:"I have put away almost all the shoes",pt:"Eu ajuntei quase todos os calçados"}]},
      {term:"put up",desc:"Com up, pendurar algo na parede.",ex:[{en:"I have put up a notice on the wall",pt:"Eu pendurei um aviso na parede"},{en:"I have put up a picture on the wall",pt:"Eu pendurei um quadro na parede"}]},
      {term:"stocking up",desc:"Stock = estocar. Com up, estocar uma grande quantidade para uso futuro.",ex:[{en:"I am stocking up food for emergencies",pt:"Eu estou estocando comida para emergências"},{en:"I am stocking up drinks for the party",pt:"Eu estou estocando bebidas para a festa"}]}
