      {term:"broken into",desc:"Break = quebrar. Com into, subitamente começar a fazer algo (entrar num ramo).",ex:[{en:"I have broken into the music industry",pt:"Eu entrei na indústria da música"}]},
      {term:"noted down",desc:"Note = notar. Com down, fazer uma anotação.",ex:[{en:"I have noted down everything they said",pt:"Eu anotei tudo que eles disseram"},{en:"I have noted down what they said",pt:"Eu anotei o que eles disseram"}]},
      {term:"stepped down",desc:"Step = pisar. Com down, renunciar uma posição.",ex:[{en:"I have stepped down as a director",pt:"Eu renunciei de ser diretor"},{en:"I have stepped down as a manager",pt:"Eu renunciei de ser gerente"}]},
      {term:"backed up",desc:"Back = dar suporte. Com up, fazer backup de arquivos.",ex:[{en:"I have backed up your contacts",pt:"Eu fiz backup dos seus contatos"},{en:"I have backed up my camera roll",pt:"Eu fiz backup da minha câmera"}]},
      {term:"carried out",desc:"Com out, executar uma tarefa difícil.",ex:[{en:"I have carried out all the tasks",pt:"Eu executei todas as tarefas"},{en:"I have carried out almost all the survey",pt:"Eu executei quase toda a enquete"}]},
      {term:"come up",desc:"Come = vir. Com up, surgir com uma ideia.",ex:[{en:"I have come up with a business idea",pt:"Eu vim com uma ideia de negócio"},{en:"I have come up with a great title",pt:"Eu vim com um ótimo título"}]},
      {term:"gone through",desc:"Go = ir. Com through, passar por uma situação difícil.",ex:[{en:"I have gone through a spell of change",pt:"Eu passei por um período de mudança"},{en:"I have gone through a moment of instability",pt:"Eu passei por um momento de instabilidade"}]}
